import numpy as np
def cross_entropy(true_probs, pred_probs):
    true_probs = np.array(true_probs)
    pred_probs = np.array(pred_probs)
    return -np.sum(true_probs * np.log2(pred_probs))

print(cross_entropy([1, 0, 0], [0.7, 0.2, 0.1]))   # low-ish, correct class got the highest probability

def binary_cross_entropy(y_true, y_pred):
    return -(y_true * np.log(y_pred) + (1 - y_true) * np.log(1 - y_pred))

print(binary_cross_entropy(1, 0.9))   # small loss, confident and correct
print(binary_cross_entropy(1, 0.1))   # large loss, confident and wrong

def stable_log_softmax(logits):
    shifted = logits - np.max(logits)   # subtract max for numerical stability
    return shifted - np.log(np.sum(np.exp(shifted)))

print(stable_log_softmax(np.array([1000, 1001, 999])))   # would overflow without the shift
